INSERT INTO public.saved_quotes(id,user_id,email,resume_token,quote_state,deposit_status,deposit_amount,quote_pdf_path,quote_pdf_sha256,customer_full_name,customer_phone,customer_address_line1,customer_city,customer_region,customer_postal_code,customer_country)
SELECT x.id,s.user_id,s.email,'dep_'||left(replace(x.id::text,'-',''),24),s.quote_state,'pending',s.deposit_amount,'saved-quotes/'||x.id||'/quote.pdf',s.quote_pdf_sha256,s.customer_full_name,s.customer_phone,s.customer_address_line1,s.customer_city,s.customer_region,s.customer_postal_code,s.customer_country
FROM public.saved_quotes s CROSS JOIN (VALUES ('77777777-7777-4777-8777-777777777777'::uuid),('78787878-7878-4878-8878-787878787878'::uuid)) x(id) WHERE s.id='73737373-7373-4373-8373-737373737373';
INSERT INTO public.native_deposit_intents(id,child_id,parent_session_id,saved_quote_id,owner_user_id,motor_id,amount_cents,currency,merchandise_cents,document_sha256,document_path,policy_version,policy_code,terms_version,catalog_model_number,horsepower,status,expires_at)
SELECT s.id,'ndc_'||replace(s.id::text,'-',''),'chk_synthetic',s.id,s.user_id,'36363636-3636-4636-8636-363636363636',50000,'CAD',1400000,s.quote_pdf_sha256,s.quote_pdf_path,'deposit-policy/v1','in_stock_refundable','hbw-reservation-terms/2026-04-08','90ELPT',90,'requires_escalation',now()+interval '1 hour' FROM public.saved_quotes s WHERE s.id IN ('77777777-7777-4777-8777-777777777777','78787878-7878-4878-8878-787878787878');
SET ROLE service_role;
SELECT public.record_native_deposit_buyer_approval(id,child_id,saved_quote_id,motor_id,amount_cents,document_sha256,policy_version,policy_code,terms_version,now()+interval '10 minutes') FROM public.native_deposit_intents WHERE id IN ('77777777-7777-4777-8777-777777777777','78787878-7878-4878-8878-787878787878');
SELECT public.claim_native_deposit_attempt(id,repeat(CASE WHEN id::text LIKE '77%' THEN '9' ELSE 'b' END,64),repeat('0',64),50000,'acct_synthetic',false) FROM public.native_deposit_intents WHERE id IN ('77777777-7777-4777-8777-777777777777','78787878-7878-4878-8878-787878787878');
RESET ROLE;
